[1963]={["atomIDs"]={"1963:description:1-42","1963:description:44-92","1963:description:94-138","1963:description:140-200","1963:description:205-298","1963:description:300-352","1963:description:357-409","1963:description:411-441","1963:description:443-476","1963:objective:1-80"},["opening"]="Therzok wanted a stronger Horde built through hidden strikes rather than the Warchief's caution. Tazan's dealings with Ratchet pirates held information he demanded in a satchel.",["pending"]="{actor} would recover Tazan's Satchel for Therzok.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the Tazan assignment and delivered his Satchel to Therzok.",["sourceClassMask"]="8",["sourceHash"]="a71794cf3a6297681d4048c11e793ab30713044e96aac0962ab4af1dbd291406",["sourceMapID"]="?",["sourceRaceMask"]="130",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[1978]={["atomIDs"]={"1978:description:1-14","1978:description:16-44","1978:description:46-125","1978:description:130-292","1978:description:297-323","1978:description:328-356","1978:objective:1-85"},["opening"]="Andron's ledger had exposed Syndicate dealings to Carkad. Admission to the Deathstalkers accompanied a final delivery of the evidence to Varimathras himself.",["pending"]="{actor} planned to deliver Andron's Ledger to Varimathras.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered Andron's Ledger to Varimathras.",["sourceClassMask"]="8",["sourceHash"]="0dab743c523e4a82a5e20a9ff3b3e4916f41c38936b512600894f412ddf1513d",["sourceMapID"]="?",["sourceRaceMask"]="16",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[1998]={["aftermath"]="Carkad judged the accumulated service sufficient to consider further training in the shadow arts.",["atomIDs"]={"1998:description:1-108","1998:description:110-241","1998:description:246-284","1998:description:286-371","1998:description:376-502","1998:objective:1-102"},["endingAtomIDs"]={"1998:completion:1-21","1998:completion:23-198"},["opening"]="Varimathras believed Thatros led undead established in Silverpine. Carkad sent a trusted operative to the decrepit Lordamere dock, where reports placed the target.",["pending"]="{actor} intended to bring Fenwick Thatros's head to Carkad.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the Thatros assignment and delivered his head to Mennet Carkad.",["sourceClassMask"]="8",["sourceHash"]="6e29d96cee61329e8f02fc85b2173082e63fba141b1348c18b862920591a33eb",["sourceMapID"]="?",["sourceRaceMask"]="16",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[1999]={["aftermath"]="Carkad praised the lockpicking displayed in the recovery and regarded his trust in the operative as justified.",["atomIDs"]={"1999:description:1-122","1999:description:124-180","1999:description:182-271","1999:description:276-302","1999:description:304-375","1999:description:377-468","1999:objective:1-102"},["endingAtomIDs"]={"1999:completion:1-14","1999:completion:16-113","1999:completion:118-165","1999:completion:167-235"},["opening"]="A prisoner's admissions pointed to Kirin Tor documents at Ambermill. Carkad assigned their recovery to the Deathstalkers, with lockpicking tools from Estelle required for the entry.",["pending"]="{actor} meant to recover the Dalaran Status Report.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the Dalaran Status Report to Mennet Carkad.",["sourceClassMask"]="8",["sourceHash"]="8b1e47272213fb82ec8fe67db035740363f4ac96e9e5d50e52968d6207faa444",["sourceMapID"]="?",["sourceRaceMask"]="16",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2038]={["atomIDs"]={"2038:description:1-160","2038:description:162-226","2038:description:231-289","2038:description:291-305","2038:objective:1-34","2038:objective:39-121"},["opening"]="A crash in the Loch was only the start of Bingles' troubles. Island troggs stole his tools and Blastencapper explosives, leaving him without both his gyrocopter and the supplies he considered vital to Gnomeregan's cause.",["pending"]="{actor} meant to recover Bingles' wrench, screwdriver, hammer and Blastencapper.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} returned Bingles' Wrench, Screwdriver, Hammer and Blastencapper to him.",["sourceHash"]="50dec45d3f359bee001014fd03c546f4b4ffe4e263346bbcce2d582470ba21c4",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2039]={["atomIDs"]={"2039:description:1-32","2039:description:34-129","2039:description:131-173","2039:description:178-215","2039:description:217-248","2039:objective:1-41"},["opening"]="Bingles had failed to report for over a week after a reconnaissance mission above Gnomeregan. Gnoarn feared an explosion, but the last sighting over the Loch left his fate uncertain.",["pending"]="{actor} meant to find Bingles Blastenheimer in Loch Modan.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} found Bingles Blastenheimer.",["sourceClassMask"]="?",["sourceHash"]="f5c5e71f9f505d135d0c14422120ec21f5713091e2b4fdecc75b2a0eb6734689",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2040]={["atomIDs"]={"2040:description:1-66","2040:description:68-119","2040:description:124-177","2040:description:179-236","2040:description:238-438","2040:objective:1-103"},["opening"]="Shoni's planned underground assault on Gnomeregan needed more power for the excavation machines. A functioning shredder deep in the Deadmines offered the intact supply that could break the rocky border.",["pending"]="{actor} planned to retrieve the Gnoam Sprecklesprocket for Shoni.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the Gnoam Sprecklesprocket to Shoni the Shilent.",["sourceClassMask"]="?",["sourceHash"]="be5f487ac4c9178365979b3c5fee99cffb0cb5342bbd2e0ff088c4b07dbba686",["sourceMapID"]="?",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2041]={["atomIDs"]={"2041:description:1-10","2041:description:12-64","2041:description:69-160","2041:description:162-224","2041:description:229-288","2041:description:293-306","2041:objective:1-42"},["opening"]="Gnoarn directed possible recruits toward the underground assault on Gnomeregan. Shoni commanded the work in Stormwind and needed help with the excavation machines.",["pending"]="{actor} intended to meet Shoni the Shilent.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} spoke with Shoni the Shilent in Stormwind.",["sourceClassMask"]="?",["sourceHash"]="236eac17a737222a03f66903375e3b2df1e3c5c75f0007a5757b75e3bff176c7",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2078]={["atomIDs"]={"2078:description:1-43","2078:description:48-131","2078:description:136-226","2078:objective:1-80"},["opening"]="Gelkak entrusted a key intended for his mechanical first mate. He wanted the Threshwackonator 4100 led back into his service, with revenge on the murlocs in mind.",["pending"]="{actor} intended to find the Threshwackonator 4100 and lead it to Gelkak.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the assignment to lead Gelkak's mechanical first mate back to him.",["sourceHash"]="9c2ddc22fc50828f9ea4a8aaa761c6c971e4320809e3c7f8d42ae750b7f7c5a3",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2098]={["atomIDs"]={"2098:description:1-46","2098:description:48-87","2098:description:89-158","2098:description:163-219","2098:description:224-340","2098:description:342-476","2098:objective:1-68"},["opening"]="A wreck and a shattered key had left Gelkak without his first mate. He saw crawlers, foreststriders and murlocs scavenging after he washed ashore, pointing the search for three key pieces toward Darkshore's creatures.",["pending"]="{actor} meant to recover all three pieces of Gelkak's Key.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} returned the three pieces of Gelkak's Key to Gelkak Gyromast.",["sourceHash"]="bb764de9b818b6d80e30501da2f5d55c8a4e70d336efe380e72aa3e4d8a28f96",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2158]={["aftermath"]="Farley offered a seat by the fire and hospitality for the tired and cold.",["atomIDs"]={"2158:description:1-139","2158:description:144-199","2158:description:201-291","2158:description:296-384","2158:objective:1-52"},["endingAtomIDs"]={"2158:completion:1-63","2158:completion:65-122","2158:completion:127-194"},["opening"]="Falkhaan recommended his friend Farley's inn down the southern road. The Lion's Pride offered a place for tired travelers to rest, with the possibility of a welcome for anyone arriving on his recommendation.",["pending"]="{actor} would seek Innkeeper Farley at the Lion's Pride.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} met Farley at the Lion's Pride Inn.",["reviewStatus"]="AUTHOR_REVIEWED_INDEPENDENT_REVIEW_PENDING",["sourceHash"]="c1853695ccaf1db612fcf5a9f5d1379eb66ca9fba96571c1513c04577007c9a9",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2159]={["atomIDs"]={"2159:description:1-20","2159:description:23-43","2159:description:46-115","2159:description:118-194","2159:description:199-234","2159:description:237-295","2159:description:298-334","2159:objective:1-50"},["opening"]="Porthannius had to remain with Shadowglen's druids while a package of herbs waited for delivery. The road south led to Dolanaar's inn and its keeper, Keldamyr.",["pending"]="{actor} planned to take the Dolanaar Delivery to Innkeeper Keldamyr.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the herb package to Innkeeper Keldamyr.",["sourceHash"]="6df9db7a763c51eeeeae88d1876ff8c6edc52e88a0ea1d9f3faae4261b3a3663",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2160]={["atomIDs"]={"2160:description:1-4","2160:description:6-39","2160:description:41-144","2160:description:149-196","2160:description:198-278","2160:description:283-351","2160:description:353-448","2160:objective:1-68"},["opening"]="Hands Springsprocket could not get through the pass and expected no mountaineer escort for days. A traveler headed to Kharanos could carry the inn's supplies to Tannok Frosthammer in the meantime.",["pending"]="{actor} planned to take the Crate of Inn Supplies to Tannok.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the Crate of Inn Supplies to Tannok Frosthammer.",["sourceHash"]="d53ed52c5c7589f98e81d885bd0274e5ee546bda58d7df2e463d5e6839d56fd5",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2161]={["atomIDs"]={"2161:description:1-10","2161:description:13-28","2161:description:33-59","2161:description:62-127","2161:description:130-228","2161:description:231-259","2161:description:262-351","2161:description:356-378","2161:description:381-415","2161:description:418-434","2161:description:439-487","2161:description:490-499","2161:objective:1-53"},["opening"]="Ukor had carried food through dangerous country only to find the Valley did not need it. He feared retracing the road to Razor Hill with the load.",["pending"]="{actor} planned to return Ukor's food to Grosk.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the burden to Razor Hill's inn.",["sourceHash"]="0675b9c67a9882ec17d8aac5265afbcfffea70d453a4f3ff367bc4b807fee176",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2178]={["atomIDs"]={"2178:description:1-34","2178:description:36-81","2178:description:83-92","2178:description:97-151","2178:description:156-240","2178:description:245-442","2178:objective:1-64"},["opening"]="Alanndarian's strider stew filled the air with an invitation to learn. Five portions of meat would first demonstrate the ability to handle its quarry rather than merely enjoy the recipe.",["pending"]="{actor} intended to bring five Strider Meat to Alanndarian.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered five Strider Meat to Alanndarian Nightsong.",["sourceClassMask"]="?",["sourceHash"]="1fe10e5f6eeeff3e431ba642b42637f74291f51a7871e6740cb90b280e8240e1",["sourceMapID"]="?",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2198]={["aftermath"]="Talvash confirmed his craftsmanship but demanded assistance before giving further information.",["atomIDs"]={"2198:description:1-99","2198:description:102-182","2198:description:185-269","2198:description:272-326","2198:description:331-425","2198:description:428-475","2198:objective:1-90"},["endingAtomIDs"]={"2198:completion:1-6","2198:completion:8-47","2198:completion:49-128","2198:completion:130-163","2198:completion:165-225"},["opening"]="The tarnished necklace still showed intricate magical workmanship. Three empty settings, Ironforge's seal and tiny initials offered the first clues to its origin.",["pending"]="{actor} intended to find the necklace's maker.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} brought the necklace to Talvash.",["sourceHash"]="da7824d46cac80c055eddba9808a62134d1d3292a859257e7ba67e6ce14e313b",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2199]={["aftermath"]="Talvash identified the necklace's former paladin owner, his death in Uldaman and the three missing gems binding its magic.",["atomIDs"]={"2199:description:1-49","2199:description:52-80","2199:description:82-148","2199:description:151-210","2199:description:213-297","2199:description:302-412","2199:description:417-498","2199:objective:1-58"},["endingAtomIDs"]={"2199:completion:1-79","2199:completion:81-93","2199:completion:96-126","2199:completion:131-250","2199:completion:253-293","2199:completion:296-419","2199:completion:424-430","2199:completion:432-504"},["opening"]="Talvash blamed a competitor for the reputation that had ruined his business. Five silver bars would let him finish a rare new order in exchange for answers.",["pending"]="{actor} planned to bring the silver Talvash needed.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} supplied the five bars.",["sourceHash"]="f4aba0c4e4fa3ab3509f8cbf5b9c10b170e28655b5cdf3eea0f2842e3ef197e9",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2200]={["aftermath"]="The journal placed the ruby with Shadowforge dwarves, the topaz in a trogg urn and the sapphire with the trogg elder.",["atomIDs"]={"2200:description:1-73","2200:description:76-140","2200:description:145-279","2200:description:284-407","2200:description:410-501","2200:objective:1-84","2200:objective:87-148"},["endingAtomIDs"]={"2200:completion:1-140","2200:completion:145-256","2200:completion:261-367","2200:completion:372-433"},["opening"]="Talvash denied the rumor that his work cursed its owner. He offered restoration in exchange for the missing gems and a restored reputation, beginning with the paladin's remains.",["pending"]="{actor} meant to seek clues around the slain paladin.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} found the paladin's remains and examined the evidence.",["sourceHash"]="cfcdf73e5b01b74220b864b4959849476a52119e420ba3333626c459746517e2",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2201]={["aftermath"]="Talvash confirmed the stones but explained that restoration still required a new power source.",["atomIDs"]={"2201:description:1-124","2201:description:127-278","2201:description:283-351","2201:description:354-480","2201:objective:1-73","2201:objective:76-179","2201:objective:184-212","2201:objective:215-275","2201:objective:278-369","2201:objective:374-434"},["endingAtomIDs"]={"2201:completion:1-37","2201:completion:40-48","2201:completion:51-101","2201:completion:106-158","2201:completion:161-238","2201:completion:241-293","2201:completion:296-341"},["opening"]="The paladin's notes supplied locations, if their observations remained accurate. Talvash's scrying phial would report the search once all three stones were gathered.",["pending"]="{actor} intended to recover the gems and contact Talvash.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} assembled the three gems and contacted their maker.",["sourceHash"]="960974c3148691be838e8177bed9d6beecf629030b2fc8e3ae246f3ea7a43762",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2202]={["atomIDs"]={"2202:description:1-73","2202:description:76-199","2202:description:202-278","2202:description:283-338","2202:description:341-402","2202:description:407-495","2202:objective:1-59"},["opening"]="Jarkal wanted to explore the alchemical use of Uldaman's magenta fungus. Caps could be found from the first tunnels to deeper reaches, with poisonous spores a danger during collection.",["pending"]="{actor} planned to gather twelve caps for Jarkal.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the fungus caps to Kargath.",["sourceHash"]="dd62b6eed8bf72fcd514afd22f223c197f5886ee0f282c5ac9a2a4ec77a80bfb",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2203]={["atomIDs"]={"2203:description:1-37","2203:description:40-113","2203:description:115-168","2203:description:171-186","2203:description:191-341","2203:description:344-402","2203:description:405-453","2203:description:458-495","2203:objective:1-85","2203:objective:88-155"},["opening"]="Jarkal's next task used three attuned vessels to draw blood from scorched guardians. Each use risked enraging the dragon before the sample was complete.",["pending"]="{actor} meant to fill all three thaumaturgy vessels.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} returned the filled vessels to Jarkal.",["sourceHash"]="02c0805f56dc872f99b03f557b133664db0984e81d3fce8227f562ee219d07b8",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2204]={["aftermath"]="Talvash prepared to fuse the source with the restored necklace and looked for his spell focus.",["atomIDs"]={"2204:description:1-117","2204:description:120-187","2204:description:190-275","2204:description:278-335","2204:description:340-405","2204:description:408-497","2204:objective:1-130"},["endingAtomIDs"]={"2204:completion:1-76","2204:completion:79-201","2204:completion:204-256","2204:completion:261-287","2204:completion:290-318","2204:completion:321-362"},["opening"]="Talvash proposed taking energy from Uldaman's strongest construct. Without that source, reunited gems alone could not restore the necklace's magic.",["pending"]="{actor} intended to bring a construct's power source to Talvash.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the power source in Ironforge.",["sourceHash"]="25259ddc756786b2aa46e5291967e4c81351ee8e4c4908b084964175fb275f61",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2205]={["atomIDs"]={"2205:description:1-10","2205:description:12-68","2205:description:70-194","2205:description:196-279","2205:description:284-374","2205:description:379-391","2205:objective:1-81"},["opening"]="Keryn disguised an introduction as a dismissive delivery. Whatever her opinion of the novice rogue, Shaw was to receive the package at the Barracks and might offer work afterward.",["pending"]="{actor} meant to take Keryn's package to Mathias Shaw.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered Keryn Sylvius's package to Master Mathias Shaw.",["sourceClassMask"]="8",["sourceHash"]="888664f0e5e4b8e34995f57834078d673ecf19c2baf7e64635797bc0ef90761f",["sourceMapID"]="?",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2206]={["atomIDs"]={"2206:description:1-83","2206:description:85-251","2206:description:256-333","2206:description:335-405","2206:description:410-496","2206:objective:1-85"},["opening"]="Shaw's reports placed Defias smuggling at Jerod's Landing, linking Redridge goods to Westfall. The dockmaster's schedule could expose the traffic if taken without compromising the hidden operative.",["pending"]="{actor} planned to recover the Shipping Schedule from the Defias Dockmaster.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the Shipping Schedule to Master Mathias Shaw.",["sourceClassMask"]="8",["sourceHash"]="d72e82541d1fc844f2805caa948e92884313453e78643d5c9c3c6640e317e554",["sourceMapID"]="?",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2218]={["atomIDs"]={"2218:description:1-43","2218:description:45-96","2218:description:98-158","2218:description:163-199","2218:description:201-239","2218:description:244-339","2218:description:341-412","2218:description:414-452","2218:objective:1-43"},["opening"]="Hogral offered purpose through a less respectable guild. The road to Ironforge's Forlorn Cavern led to Hulfdan and the thieves who could find work for a wandering rogue.",["pending"]="{actor} intended to speak with Hulfdan Blackbeard.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} spoke with Hulfdan Blackbeard in Ironforge.",["sourceClassMask"]="8",["sourceHash"]="6408ecfec7190aaf19059bf3c91d5313dfb5155171ce061ae1c8caa5a924a860",["sourceMapID"]="?",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2238]={["atomIDs"]={"2238:description:1-61","2238:description:63-121","2238:description:126-158","2238:description:160-178","2238:description:180-197","2238:description:202-340","2238:description:345-428","2238:description:430-484","2238:description:486-496","2238:objective:1-34"},["opening"]="Hulfdan wanted the king's quarry wealth shared without the king knowing. Onin, hidden near Gnomeregan, could provide the report needed for the Hidden Circle's next theft.",["pending"]="{actor} meant to find Onin MacHammar.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} found Onin MacHammar near Gnomeregan.",["sourceClassMask"]="8",["sourceHash"]="7f85ccb4ebf99e8ac62050b3cc04baba8c449b128c47f10c209a814157f70b8a",["sourceMapID"]="?",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2239]={["atomIDs"]={"2239:description:1-11","2239:description:13-92","2239:description:97-371","2239:description:376-402","2239:description:404-456","2239:objective:1-48"},["opening"]="Onin had watched armored steam tanks pass almost daily. His report traced the pickup, refueling and long return route, giving Hulfdan the movement pattern needed to plan a strike.",["pending"]="{actor} planned to take Onin's Report to Hulfdan.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered Onin's Report to Hulfdan Blackbeard.",["sourceClassMask"]="8",["sourceHash"]="b342ce6f5e5e6a85cc0492d62a15c7bf989d02ccf1cc6403f123ad070489859d",["sourceMapID"]="?",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2240]={["aftermath"]="Stormpike accepted the discovery and hoped it would renew efforts to reclaim Uldaman, which remained outside Ironforge's control.",["atomIDs"]={"2240:description:1-25","2240:description:30-103","2240:description:106-166","2240:description:169-209","2240:description:214-272","2240:description:275-313","2240:description:315-367","2240:description:372-483","2240:objective:1-87"},["endingAtomIDs"]={"2240:completion:1-38","2240:completion:40-47","2240:completion:49-114","2240:completion:119-132","2240:completion:134-221","2240:completion:223-328"},["opening"]="Baelog knew how to open the great door to Khaz'mul but could not leave his band. His journal passed the exploration onward, with findings due to Stormpike.",["pending"]="{actor} planned to read the instructions and explore the chamber.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} reported the chamber's exploration to Stormpike.",["sourceHash"]="819411f12d60e1c1c933e4f6cb57cb94eb524752d2d53e5583538add2a8fe075",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2241]={["atomIDs"]={"2241:description:1-47","2241:description:52-110","2241:description:112-169","2241:description:171-279","2241:description:281-297","2241:description:302-322","2241:description:328-425","2241:description:430-466","2241:description:468-509","2241:objective:1-42"},["opening"]="Jannok's fixation had not persuaded Syurna to receive him. He sought a rogue messenger for a rose, hoping an unwanted correspondence might resume through another person.",["pending"]="{actor} intended to take Jannok's Rose to Syurna.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered Jannok's Rose to Syurna.",["sourceClassMask"]="8",["sourceHash"]="4704dc321d649d6fc8f76501ad70bd6fba6db2158debdd61133c7778db392989",["sourceMapID"]="?",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2242]={["atomIDs"]={"2242:description:1-116","2242:description:118-188","2242:description:193-250","2242:description:252-348","2242:description:350-383","2242:description:388-459","2242:objective:1-81"},["opening"]="Syurna thought Sethir might explain Teldrassil's troubles, but approaches by force or diplomacy had failed disastrously. Stealth offered another chance to learn what the satyr carried at the Oracle Glade's edge.",["pending"]="{actor} meant to recover clues from Sethir the Ancient for Syurna.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the recovered Sethir clues to Syurna.",["sourceClassMask"]="8",["sourceHash"]="9abfe35328f1507c265feffb03164177c6adc47db853f442e29c3db2b67f3ff3",["sourceMapID"]="?",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2258]={["aftermath"]="Jarkal accepted the stock and proposed harder work inside Uldaman.",["atomIDs"]={"2258:description:1-45","2258:description:48-152","2258:description:157-284","2258:description:287-405","2258:description:410-474","2258:description:477-492","2258:objective:1-117"},["endingAtomIDs"]={"2258:completion:1-14","2258:completion:16-65","2258:completion:67-95","2258:completion:100-159","2258:completion:161-231","2258:completion:233-340","2258:completion:345-394"},["opening"]="Jarkal's stock needed materials from three kinds of local creatures. Buzzard gizzards, coyote fangs and elemental shards formed the first collection.",["pending"]="{actor} meant to replenish Jarkal's three reagent supplies.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} brought the requested materials to Kargath.",["sourceHash"]="ab456567de778f45c6621890222cb49205e391f76f788de8a77cdb5f6c6b9f44",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2259]={["atomIDs"]={"2259:description:1-53","2259:description:55-107","2259:description:109-119","2259:objective:1-40"},["opening"]="This summons concerned Erion rather than Syurna. Jannok directed the rogue promptly toward the Cenarion Enclave for the requested meeting.",["pending"]="{actor} planned to contact Erion Shadewhisper.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} spoke with Erion Shadewhisper in Darnassus.",["sourceClassMask"]="8",["sourceHash"]="dece4fedf29261e23c40a46bf4423da8b573037ca00f7addb928aa8ed6dcc998",["sourceMapID"]="?",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2260]={["atomIDs"]={"2260:description:1-47","2260:description:49-119","2260:description:124-235","2260:description:240-266","2260:description:268-360","2260:objective:1-65"},["opening"]="Stormwind Intelligence had requested the rogue by name. Erion considered the dangerous journey worthwhile for training under SI:7 and sent the next meeting to Renzik in Old Town.",["pending"]="{actor} intended to seek Renzik the Shiv in Stormwind.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} spoke with Renzik the Shiv.",["sourceClassMask"]="8",["sourceHash"]="78c1d67dc26d097e1b460c107fa2a691be47d03eeeff6d537735586fc913b0ab",["sourceMapID"]="?",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2278]={["aftermath"]="The keeper said synthesis was complete and directed another access to obtain a personal copy.",["atomIDs"]={"2278:description:1-127","2278:description:130-166","2278:description:169-249","2278:description:254-266","2278:description:269-295","2278:description:298-414","2278:description:419-486","2278:objective:1-62","2278:objective:65-145"},["endingAtomIDs"]={"2278:completion:1-182","2278:completion:184-233","2278:completion:235-264","2278:completion:269-305","2278:completion:307-377"},["opening"]="Four sigil-marked discs called forth a stone keeper. The apparition described a record of the creators' work with the Earthen, preserving ancient knowledge in the chamber.",["pending"]="{actor} intended to hear the keeper's lore and activate the discs.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} learned the offered lore and accessed the record.",["sourceHash"]="b1024983c8bafa37f74adeb04e32aae804f5743997fe2c26a9e1d275a670e087",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2279]={["aftermath"]="Magellas recognized a discovery that might prove the dwarves' enchanted origin, without treating the research as already concluded.",["atomIDs"]={"2279:description:1-66","2279:description:69-144","2279:description:149-206","2279:description:209-262","2279:description:267-374","2279:description:377-496","2279:objective:1-91"},["endingAtomIDs"]={"2279:completion:1-25","2279:completion:35-55","2279:completion:60-70","2279:completion:75-103","2279:completion:108-119","2279:completion:124-194","2279:completion:197-250","2279:completion:253-353","2279:completion:356-451"},["opening"]="A further touch produced a miniature copy of the ancient records. Ironforge's Explorers' League offered a destination for this newly portable history.",["pending"]="{actor} planned to bring the miniature records to the League.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the copy to Magellas.",["sourceHash"]="4db2b872ce61929d0fe167d30942095e2345828cd36bb12ce54874cccd5a7fdf",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2280]={["aftermath"]="The sage sensed long-kept secrets in the discs and welcomed their arrival.",["atomIDs"]={"2280:description:1-66","2280:description:69-144","2280:description:149-206","2280:description:209-262","2280:description:267-374","2280:description:377-489","2280:objective:1-94"},["endingAtomIDs"]={"2280:completion:1-25","2280:completion:30-51","2280:completion:53-142","2280:completion:144-187"},["opening"]="The great records yielded a smaller version that could leave Uldaman. Thunder Bluff's sages offered another scholarly destination for the preserved history.",["pending"]="{actor} meant to carry the miniature records to a sage.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the copy to Truthseeker.",["sourceHash"]="ea02351c1e12446c2bc04fbd52a249f589eea196d7810fdc834eeacaf836d501",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2281]={["atomIDs"]={"2281:description:1-50","2281:description:52-103","2281:description:105-168","2281:description:173-261","2281:description:263-357","2281:objective:1-75"},["opening"]="Renzik refused to send an unprepared rogue into the field. Lucius at Lakeshire's docks could supply the training needed before more dangerous intelligence work.",["pending"]="{actor} meant to meet Lucius in Lakeshire.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} spoke with Lucius in Redridge.",["sourceClassMask"]="8",["sourceHash"]="c3868691dd028cb81effcbbc98dd56c7cbaccd02873695cf90cb0cab411b5c1f",["sourceMapID"]="?",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2282]={["atomIDs"]={"2282:description:1-43","2282:description:45-126","2282:description:131-177","2282:description:179-233","2282:description:235-251","2282:description:253-322","2282:objective:1-90"},["opening"]="Lucius's chest at Alther's Mill held the token for his lesson. Recovering it would demonstrate the finesse behind the promised Certificate of Thievery.",["pending"]="{actor} planned to open Lucius's Lockbox and return the Token of Thievery.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the Token of Thievery to Lucius after the lockbox assignment.",["sourceClassMask"]="8",["sourceHash"]="34e1e74ffd38eb8f312531725b51cfad875fc12bd6e828cac23f122ce5c5f899",["sourceMapID"]="?",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2283]={["aftermath"]="Dran rejected the setting's value without its missing gems and demanded further recovery.",["atomIDs"]={"2283:description:1-64","2283:description:69-113","2283:description:116-183","2283:description:186-249","2283:description:252-321","2283:description:326-385","2283:description:388-480","2283:objective:1-105","2283:objective:108-135"},["endingAtomIDs"]={"2283:completion:1-13","2283:completion:16-50","2283:completion:53-84","2283:completion:89-136","2283:completion:139-172","2283:completion:175-203","2283:completion:206-250","2283:completion:255-290","2283:completion:292-341","2283:completion:344-392"},["opening"]="Dran sought a valuable necklace reportedly lost with a paladin in Uldaman. His salvage offer allowed for damage but assumed the ruby, sapphire and topaz belonged with it.",["pending"]="{actor} intended to retrieve the necklace for Dran.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the damaged necklace.",["sourceHash"]="f429a5e44305245c86bdf212fe67dd49addc0ebe1eaeb522fc6e7dcd5d28adeb",["sourceRaceMask"]="690",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2284]={["aftermath"]="A bloodstained journal was found, but its human language still required translation.",["atomIDs"]={"2284:description:1-72","2284:description:75-130","2284:description:135-263","2284:description:266-304","2284:description:309-344","2284:description:347-404","2284:description:407-485","2284:objective:1-65"},["endingAtomIDs"]={"2284:completion:1-86","2284:completion:88-154","2284:completion:156-242","2284:completion:244-365","2284:completion:370-445"},["opening"]="Dran sent the search back to Uldaman for clues to the absent stones. He suggested the paladin's corpse as a possible starting point rather than a certain answer.",["pending"]="{actor} planned to investigate the paladin's remains.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} examined the remains for a lead.",["sourceHash"]="7a5afd4ffd779f30bee19f0b0f0af64b8c2690e9631a4f1d6763e2ea8143ccca",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2298]={["atomIDs"]={"2298:description:1-185","2298:description:190-233","2298:description:235-312","2298:description:317-326","2298:description:328-388","2298:description:390-483","2298:objective:1-51"},["opening"]="The quarry plot had attracted Magni's guards before its third phase. Arrests and a name spoken during the argument led Hulfdan to advise flight to Stormwind and his old associate Renzik.",["pending"]="{actor} intended to seek Renzik in Stormwind.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} spoke with Renzik the Shiv.",["sourceClassMask"]="8",["sourceHash"]="d6a1ffb0fc241e3750e0403dbcdf5a4f1fb532f8314bc81a965a8c85b1b83b1c",["sourceMapID"]="?",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2299]={["atomIDs"]={"2299:description:1-24","2299:description:26-75","2299:description:77-122","2299:description:127-186","2299:objective:1-54"},["opening"]="Hulfdan had been searching for the absent rogue, and Hogral feared royal irons might explain the delay. An immediate return to Ironforge was requested.",["pending"]="{actor} meant to meet Hulfdan Blackbeard.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} spoke with Hulfdan Blackbeard in Ironforge.",["sourceClassMask"]="8",["sourceHash"]="d6e42cd6ae959ecd4c8f22c55b55ab2124d6904dc3eb80616cd26033c599a74a",["sourceMapID"]="?",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2300]={["atomIDs"]={"2300:description:1-33","2300:description:38-103","2300:objective:1-51"},["opening"]="Renzik had asked for the rogue, and Keryn warned against keeping Shaw's deputy waiting. The next report belonged at SI:7 in Stormwind.",["pending"]="{actor} planned to seek Renzik the Shiv.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} spoke with Renzik the Shiv in Stormwind.",["sourceClassMask"]="8",["sourceHash"]="1d15088f3b46e688ae09a6c5e82c3419572b31762836f14c5c5ce6817a617c43",["sourceMapID"]="?",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2318]={["aftermath"]="Jarkal recognized the necklace business and offered another arrangement alongside the salvage contract.",["atomIDs"]={"2318:description:1-107","2318:description:110-282","2318:description:285-322","2318:objective:1-53","2318:objective:56-128"},["endingAtomIDs"]={"2318:completion:1-62","2318:completion:64-98","2318:completion:100-160","2318:completion:165-174","2318:completion:176-218","2318:completion:220-291","2318:completion:293-354","2318:completion:359-479","2318:completion:481-500"},["opening"]="The unread journal blocked further progress. Kargath was the nearest likely place to find someone capable of translating it.",["pending"]="{actor} meant to seek a translator at Kargath.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} brought the journal to Jarkal.",["sourceHash"]="d74be64f79b2ad1e4ff6c1059161ab20037fc28f50b30419a495ab7c8c571fe2",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2338]={["aftermath"]="Jarkal prepared a spell to make the human journal understandable.",["atomIDs"]={"2338:description:1-92","2338:description:95-168","2338:description:171-208","2338:description:211-312","2338:description:315-402","2338:description:407-460","2338:description:463-479","2338:objective:1-31","2338:objective:34-84"},["endingAtomIDs"]={"2338:completion:1-68","2338:completion:73-188","2338:completion:190-260","2338:completion:262-291"},["opening"]="Jarkal wanted time to study the necklace's construction. He offered translation in exchange for borrowing it while the missing gems were sought.",["pending"]="{actor} intended to lend Jarkal the necklace for study.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} entrusted the necklace to Jarkal.",["sourceHash"]="7dfc3772d88b8ff34b19a4f5e6119e7ca4d064e53d086ca425d2cddfcca34c08",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2339]={["aftermath"]="Jarkal said his study had taught him to reproduce the necklace and prepared to analyze the gems before their return.",["atomIDs"]={"2339:description:1-60","2339:description:63-173","2339:description:178-252","2339:description:255-286","2339:description:289-405","2339:description:408-447","2339:description:452-502","2339:objective:1-123","2339:objective:126-217","2339:objective:222-250","2339:objective:253-313","2339:objective:316-407","2339:objective:410-470"},["endingAtomIDs"]={"2339:completion:1-19","2339:completion:22-90","2339:completion:93-204","2339:completion:209-349","2339:completion:352-392"},["opening"]="The translated journal identified the stones' hiding places. Jarkal added a separate requirement: energy from a powerful construct, which he believed could restore the magic.",["pending"]="{actor} planned to gather all three gems and a power source.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the gems and source to Jarkal.",["sourceHash"]="0a07266f630f39e116d4dcc0d9d959ebb686552133945c93030419f998775023",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2340]={["aftermath"]="Dran confirmed all the contracted materials were present and closed the business for the time being.",["atomIDs"]={"2340:description:1-78","2340:description:81-160","2340:description:162-168","2340:description:173-284","2340:description:289-369","2340:description:372-477","2340:objective:1-67"},["endingAtomIDs"]={"2340:completion:1-19","2340:completion:21-53","2340:completion:59-80","2340:completion:82-85","2340:completion:90-133","2340:completion:135-207","2340:completion:209-218","2340:completion:223-275","2340:completion:277-356","2340:completion:358-377"},["opening"]="Jarkal hoped the power source would support another necklace using equivalent materials. He directed the original salvage onward while asking that their private arrangement remain concealed.",["pending"]="{actor} meant to deliver the original setting and stones to Dran.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} fulfilled the salvage delivery to Dran.",["sourceHash"]="899b80655d426a2521032b65370fb523adc588f09fad18bd9e95f3a33c482640",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2341]={["aftermath"]="Jarkal confirmed making two necklaces and retaining enough power for at least three more.",["atomIDs"]={"2341:description:1-103","2341:description:106-245","2341:objective:1-61"},["endingAtomIDs"]={"2341:completion:1-69","2341:completion:71-173","2341:completion:175-250","2341:completion:255-277","2341:completion:279-319","2341:completion:321-365"},["opening"]="The Droffers' half of the bargain was complete. A return to Kargath would reveal whether Jarkal's separate experiment had succeeded.",["pending"]="{actor} intended to ask Jarkal about the power source.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} returned to Jarkal after the salvage delivery.",["sourceHash"]="e02d086660730c7deef8efd77815a9da12627e56fd1595cacd2edff291fbfdc3",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2342]={["aftermath"]="Patrick revealed the treasured family weapon as a broom he considered worthy of the Garrett name.",["atomIDs"]={"2342:description:1-65","2342:description:68-173","2342:description:178-323","2342:description:326-418","2342:description:423-470","2342:description:473-502","2342:objective:1-136"},["endingAtomIDs"]={"2342:completion:1-38","2342:completion:41-100","2342:completion:105-130","2342:completion:133-180","2342:completion:183-206"},["opening"]="Patrick resented sweeping bat pens with an inferior broom. The family chest in Uldaman held the weapon he believed would restore a Garrett's standing.",["pending"]="{actor} planned to recover the family treasure.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} brought Patrick's treasure to the Undercity.",["sourceHash"]="fd67dcd5c83240ae981799537b8c54ad1e69d91d2d804fabdbc7c0b90f76ce6b",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2358]={["atomIDs"]={"2358:description:1-70","2358:description:72-208","2358:description:213-287","2358:description:289-339","2358:description:344-405","2358:objective:1-60"},["opening"]="Arantir had crossed oceans searching for horns stolen from Ravenholdt. Discovery that Blackrock orcs held them turned that long pursuit toward a recovery from the clan and a return to Lakeshire.",["pending"]="{actor} intended to recover the Horns of Nez'ra for Arantir's Shadow.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the Horns of Nez'ra to Arantir's Shadow.",["sourceClassMask"]="8",["sourceHash"]="0cd7f5f1ba7ddc456584b18903ba78fde459f5ef5a4ad97b3b38afcf9fb7a3e5",["sourceMapID"]="?",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2359]={["atomIDs"]={"2359:description:1-47","2359:description:49-138","2359:description:143-156","2359:description:158-187","2359:description:189-233","2359:description:238-327","2359:description:329-378","2359:description:383-452","2359:description:454-488","2359:objective:1-103","2359:objective:105-173","2359:objective:175-229"},["opening"]="Kearnen watched an unusual Duskwood shipment bring inhuman guards to the tower. She suspected they protected a chest, with a spiked zombie holding the key required to reach its contents.",["pending"]="{actor} would steal the tower key, open the Duskwood Chest and report its information to Shaw.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the tower-and-chest assignment and brought the recovered information to Mathias Shaw.",["sourceClassMask"]="8",["sourceHash"]="f4046b3c77d0020577c8cd3f0a9221849c038e09259ed0100feb7fdd3ddfd3d0",["sourceMapID"]="?",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2360]={["atomIDs"]={"2360:description:1-26","2360:description:28-104","2360:description:109-307","2360:description:312-373","2360:description:375-414","2360:description:419-505","2360:objective:1-62"},["opening"]="Defias had occupied an abandoned tower southeast of Sentinel Hill as a smuggling base. Shaw sent the rogue to Kearnen, who was already hidden nearby watching the traffic.",["pending"]="{actor} meant to contact Agent Kearnen in Westfall.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} spoke with Agent Kearnen near the tower.",["sourceClassMask"]="8",["sourceHash"]="54b6f898c6329c2a71aada26bcf36ac8ef06db3099d66c39fda1317c3301475d",["sourceMapID"]="?",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2378]={["aftermath"]="Shenthul met the arrival from his allies with open disdain. The introduction offered no immediate assurance of his respect.",["atomIDs"]={"2378:description:1-94","2378:description:96-195","2378:description:200-255","2378:description:257-321","2378:objective:1-68"},["endingAtomIDs"]={"2378:completion:1-54","2378:completion:56-74"},["opening"]="Carkad saw promise in the operative but more training still required. The Deathstalkers' allies in the Shattered Hand offered the next school of stealth, through Shenthul in Orgrimmar.",["pending"]="{actor} planned to meet Shenthul.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} spoke with Shenthul in the Cleft of Shadow.",["sourceClassMask"]="8",["sourceHash"]="7d902df78d98cde721c3e5fae46e091bf1c09c0c6f1125da4288417c61ba6f04",["sourceMapID"]="?",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2379]={["aftermath"]="Zando'zan withdrew an earlier judgment with an apology, leaving the new introduction on a different footing.",["atomIDs"]={"2379:description:1-86","2379:description:91-172","2379:description:177-301","2379:objective:1-44"},["endingAtomIDs"]={"2379:completion:1-28","2379:completion:30-50"},["opening"]="Shenthul considered determination insufficient without practice. Zando'zan would begin the operative's training in the stealth and theft needed for the Hand's work.",["pending"]="{actor} intended to speak with Zando'zan.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} spoke with Zando'zan.",["sourceClassMask"]="8",["sourceHash"]="16ec6752c7638692564f6eeb1fac3ada7511598b3fa43b0d0e1afdbf2d3a6fbe",["sourceMapID"]="?",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2380]={["atomIDs"]={"2380:description:1-88","2380:description:90-205","2380:description:210-297","2380:objective:1-56"},["opening"]="Kaplak relayed Shenthul's personal request despite his own low opinion of the novice's skills. Northward in Orgrimmar lay the chance to learn what stealth and deception demanded.",["pending"]="{actor} meant to answer Shenthul's summons.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} spoke with Shenthul in Orgrimmar.",["sourceClassMask"]="8",["sourceHash"]="01e0b316a855c90ebff5b300583224ade2fe0a74ea41b29253b513ebb7c5ae58",["sourceMapID"]="?",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2381]={["aftermath"]="Wrenix marveled at the returned treasure, uncertain whether talent or extraordinary luck deserved the credit. He offered a share of the proceeds.",["atomIDs"]={"2381:description:1-121","2381:description:126-202","2381:description:204-261","2381:description:263-362","2381:description:367-427","2381:description:429-503","2381:objective:1-67","2381:objective:69-100","2381:objective:102-156","2381:objective:158-216","2381:objective:221-295"},["endingAtomIDs"]={"2381:completion:1-11","2381:completion:13-23","2381:completion:25-39","2381:completion:41-62","2381:completion:64-117","2381:completion:122-151","2381:completion:153-214"},["opening"]="Wrenix's previous thieves had returned in pieces from the Southsea treasure. The Tide Razor's hold remained the prize, with a training den, tools and a special response to hostile parrots among the preparations.",["pending"]="{actor} planned to retrieve the Southsea Treasure using Wrenix's supplied tools.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the Southsea Treasure to Wrenix the Wretched.",["sourceClassMask"]="8",["sourceHash"]="5c1fbcf44b5f726de5abc10ed62f6fbd72a91324d71bcb4aa76e5c069ec177af",["sourceMapID"]="?",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2382]={["aftermath"]="Wrenix recalled five earlier referrals lost to the sharks. He hoped this new arrival would fare better, keeping the warning attached to work still ahead.",["atomIDs"]={"2382:description:1-22","2382:description:24-42","2382:description:44-60","2382:description:62-128","2382:description:130-157","2382:description:166-193","2382:description:195-280","2382:objective:1-53"},["bridge"]="Zando'zan's disturbing vision gave way to a concrete destination: Wrenix in Ratchet. The visit would lead from an unsettling prophecy into practical work.",["bridgeFrom"]=2379,["bridgeReplacesSetup"]=true,["endingAtomIDs"]={"2382:completion:1-12","2382:completion:14-75","2382:completion:77-116"},["opening"]="Zando'zan's unsettling vision of Thrall's death gave way to a practical assignment. Whatever his prophecy meant, the next instruction was a visit to Wrenix in Ratchet.",["pending"]="{actor} intended to speak with Wrenix the Wretched.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} spoke with Wrenix the Wretched in Ratchet.",["sourceClassMask"]="8",["sourceHash"]="929374783120fd5759e80c8a9b4f85991aad040b03740b75d18c91842bd4ee2a",["sourceMapID"]="?",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2383]={["atomIDs"]={"2383:description:1-53","2383:description:58-84","2383:description:86-145","2383:description:147-193","2383:description:195-253","2383:objective:1-69"},["opening"]="A parchment had arrived while the novice was away. Gornek believed Frang sent it and directed the reader toward the warrior trainer taking shade outside the Den.",["pending"]="{actor} meant to read the Simple Parchment and speak with Frang.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the parchment introduction with Frang.",["sourceClassMask"]="1",["sourceHash"]="9667e740fb1159e891ddea4d1de073bea89208a13d415b810d7ad91d6d6f438f",["sourceMapID"]="?",["sourceRaceMask"]="2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2398]={["aftermath"]="Baelog was alive and greeted the arrival through a wager about how long rescue would take.",["atomIDs"]={"2398:description:1-46","2398:description:49-101","2398:description:103-134","2398:description:137-218","2398:description:223-323","2398:description:328-426","2398:description:429-485","2398:objective:1-23"},["endingAtomIDs"]={"2398:completion:1-30","2398:completion:32-73","2398:completion:78-159","2398:completion:161-239","2398:completion:244-254","2398:completion:256-288"},["opening"]="The trogg assault had cut off a small band that entered Uldaman before the attack. Stormpike feared Baelog and his companions were still trapped if they lived at all.",["pending"]="{actor} meant to locate Baelog's band.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} found Baelog in Uldaman.",["sourceHash"]="845d82bc3f98aec212eb410f6e37f1113ee9c6a096c515479b4cd5ed00de67ee",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2399]={["aftermath"]="The fronds in Denalan's garden had sprouted and grown. Their trembling growth was ready to be picked.",["atomIDs"]={"2399:completion:1-69","2399:completion:72-107"},["availabilityQualification"]={["basis"]="Catalog states positive beta server experience; confirms reported definition, not that a player can reach its giver in the target release",["currentServerPlayableConfirmed"]=false,["eligibility"]="BETA_SERVER_DEFINED_PUBLISHER_CLAIM",["sourceReceipt"]="https://www.curseforge.com/wow/addons/questdb/files/9014639 ; https://tierhall.app/wow/quests/2399 ; https://warcraftforever.games/quests/2399 ; https://wowfwiki.com/wiki/Quests"},["completionOnly"]=true,["endingAtomIDs"]={"2399:completion:1-69","2399:completion:72-107"},["factSourceMetadata"]={["finisherIDs"]={},["finisherName"]=nil,["giverIDs"]={},["giverName"]=nil},["fieldBlockers"]={"Acceptance description absent.","Acceptance objective absent.","Opening, pending intention, and personal objective discharge remain source-blocked."},["kind"]="COMPLETION_ONLY",["minimumStage"]=4,["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["sourceClassMask"]="?",["sourceHash"]="8bfa104adf95030cce19a95a2a9454860ea44e8860ba7fe8968aada5f5f54261",["sourceMapID"]="1438",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2418]={["atomIDs"]={"2418:description:1-60","2418:description:63-146","2418:description:149-235","2418:description:238-295","2418:description:300-425","2418:description:430-460","2418:description:463-506","2418:objective:1-89"},["opening"]="Rigglefuzz had taught the Shadowforge how to sustain power in two kinds of stone. Expelled afterward, he now wanted examples for devices of his own.",["pending"]="{actor} intended to gather eight stones of each type.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered both kinds of power stone to Rigglefuzz.",["sourceHash"]="a86efb24993ab8c6b63732333d51db6e9f3bc7d7387ff4ef8e5b05193be2647b",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2438]={["atomIDs"]={"2438:description:1-119","2438:description:121-229","2438:description:234-316","2438:description:318-436","2438:description:441-500","2438:objective:1-66"},["opening"]="Tallonkai's emerald dreamcatcher remained in his dresser at Starbreeze Village. Once peaceful, the settlement had fallen to corrupted furbolgs, preventing him from recovering the amulet given by Gaerolas.",["pending"]="{actor} meant to recover the Emerald Dreamcatcher for Tallonkai.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} returned the Emerald Dreamcatcher to Tallonkai Swiftroot.",["sourceHash"]="19e132e756333dff364f21040effed5893c598d0ec9198cd0ca37cfa9c14a298",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2439]={["atomIDs"]={"2439:description:1-34","2439:description:37-183","2439:description:186-250","2439:description:255-330","2439:description:333-399","2439:description:404-496","2439:objective:1-73"},["opening"]="Magellas saw the discs as a possible link to the dwarves' enchanted creation, if their lore was correct. Research would take time; a voucher at Ironforge's vault marked recognition of the find.",["pending"]="{actor} planned to take the reward voucher to Dinita Stonemantle.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the reward voucher to Dinita Stonemantle.",["sourceClassMask"]="?",["sourceHash"]="e39f33bbf2ae2d64fadad5e4879d26b6dcbddbb589c5280026fc95375c39346b",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2440]={["atomIDs"]={"2440:description:1-97","2440:description:102-190","2440:description:193-268","2440:description:271-410","2440:description:415-504","2440:objective:1-60"},["opening"]="Truthseeker remained focused on the ancient discs. A voucher sent the acknowledged service to Bena while the sage continued studying their workings.",["pending"]="{actor} planned to redeem the voucher with Bena.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered it to the alchemist.",["sourceHash"]="b5755f5e1e8db3a565de487ac22b43d12ccf37caf3f44ab644b15f4413e97794",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2458]={["aftermath"]="Fizzule accepted the contact but considered the flare excessive. For future recognition he offered a quieter signal: two blasts on a whistle.",["atomIDs"]={"2458:description:1-22","2458:description:24-54","2458:description:59-131","2458:description:133-190","2458:description:195-240","2458:description:242-281","2458:description:283-327","2458:description:329-387","2458:description:392-504","2458:objective:1-25","2458:objective:27-127","2458:objective:132-222","2458:objective:224-311","2458:objective:316-439"},["endingAtomIDs"]={"2458:completion:1-120","2458:completion:125-220"},["opening"]="A year of infiltration had placed Fizzule inside the Venture Company. Contact required two flares followed by the Hand's salute; any stranger approaching without recognition risked the agent's attack.",["pending"]="{actor} planned to signal twice, salute and contact Taskmaster Fizzule in order.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the prescribed covert contact with Taskmaster Fizzule.",["sourceClassMask"]="8",["sourceHash"]="7e9501224671c082c85e0f19b1d172332be349b3a5e4650d79036741def10c56",["sourceMapID"]="?",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2459]={["atomIDs"]={"2459:description:1-14","2459:description:16-29","2459:description:31-63","2459:description:68-139","2459:description:141-264","2459:description:266-335","2459:description:337-392","2459:description:397-424","2459:description:426-498","2459:objective:1-97"},["opening"]="The dreamcatcher was missing its emerald. Reports of Ferocitas wearing a green-glowing necklace north of Starbreeze convinced Tallonkai that the mystic leader stole the jewel, and he called for its recovery amid an attack on the corrupted band.",["pending"]="{actor} planned to seek the Missing Jewel and meet the assignment against seven Gnarlpine Mystics.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the Missing Jewel and completed the assignment against seven Gnarlpine Mystics.",["sourceHash"]="11af6e8aac175bf9cbc477a1253287762d0ed2af7cacff178935e1e84eed6dbf",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2460]={["aftermath"]="Shenthul accepted the salute and considered the operative ready to proceed.",["atomIDs"]={"2460:description:1-87","2460:description:89-152","2460:description:157-177","2460:objective:1-41"},["endingAtomIDs"]={"2460:completion:1-14","2460:completion:16-44"},["opening"]="The Shattered Salute separated members from strangers. Shenthul made its sequence a lesson to observe and repeat before further work in the Hand's name.",["pending"]="{actor} intended to perform the Shattered Salute on Shenthul.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the Shattered Salute demonstration.",["sourceClassMask"]="8",["sourceHash"]="899b61445e89495f9bfcb30fa7ce0c03f9a775a62cc6607696d5e2c864158cfa",["sourceMapID"]="?",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2478]={["aftermath"]="Shenthul spoke of Fizzule as a lost agent and treated the loss as a cost of field work. He praised the mission while warning that the returning operative's own survival still mattered.",["atomIDs"]={"2478:description:1-62","2478:description:64-143","2478:description:148-206","2478:description:208-276","2478:description:278-308","2478:description:313-436","2478:description:438-509","2478:objective:1-81","2478:objective:83-105","2478:objective:107-137","2478:objective:139-147","2478:objective:152-294","2478:objective:296-384"},["completionAttributionNotes"]={"Fizzule death is reported by Shenthul in completion response; no personal observation or cause of death is asserted."},["endingAtomIDs"]={"2478:completion:1-53","2478:completion:55-87","2478:completion:89-148","2478:completion:153-190","2478:completion:192-249"},["opening"]="Fizzule's plan used poison-weakened tower forces against their own security. The key, selected guards, Gallywix's head and his locked cache of altered mixture all formed the dangerous mission back to Shenthul.",["pending"]="{actor} would complete Fizzule's tower assignment and take Gallywix's head and mixture to Shenthul.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the key-and-tower assignment and delivered Gallywix's Head and the Cache of Zanzil's Altered Mixture to Shenthul.",["sourceClassMask"]="8",["sourceHash"]="94536c93e5ec7c09ae1758abfd22c5f982cb0d614be54df13758a5961dafe458",["sourceMapID"]="?",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2479]={["aftermath"]="Serge greeted the sickly appearance and foul smell with curiosity. The sample's arrival had reached a specialist who seemed fascinated by its effects.",["atomIDs"]={"2479:description:1-60","2479:description:65-99","2479:description:101-177","2479:objective:1-104","2479:objective:109-233","2479:objective:235-251"},["endingAtomIDs"]={"2479:completion:1-30","2479:completion:32-78","2479:completion:80-91"},["opening"]="Shenthul sent a sample to Serge Hinott as the best hope for a cure. Survival would precede the poison knowledge the Tarren Mill specialist could teach.",["pending"]="{actor} meant to deliver the Sample of Zanzil's Mixture to Serge.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the Sample of Zanzil's Mixture to Serge Hinott.",["sourceClassMask"]="8",["sourceHash"]="9a6c76204e08710a44e2a1119cbb45c1832b5686fb830575711176974486702f",["sourceMapID"]="?",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2480]={["aftermath"]="Serge announced the cure ready and advised drinking the anti-toxin to stop the creeping madness. He warned that it would do nothing for the smell.",["atomIDs"]={"2480:description:1-54","2480:description:56-70","2480:description:72-154","2480:description:159-236","2480:description:241-287","2480:objective:1-43"},["endingAtomIDs"]={"2480:completion:1-18","2480:completion:20-136"},["opening"]="Serge admired the toxin's results even while asked to cure them. Examination needed a few moments before he could complete the antidote and turn toward teaching its use.",["pending"]="{actor} planned to wait for Serge's cure.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the wait for Serge Hinott's cure preparation.",["sourceClassMask"]="8",["sourceHash"]="01c3f443255c1a6db93525d7582a7eab7d8cd68c1c579608b61a23cb1861d303",["sourceMapID"]="?",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2498]={["atomIDs"]={"2498:description:1-136","2498:description:138-184","2498:description:189-222","2498:objective:1-68"},["opening"]="Word from Lake Al'Ameth suggested Denalan might have found the cause of the timberlings' tumors. Rellian sent help back to his colleague before the discovery lost time.",["pending"]="{actor} planned to return to Denalan with Rellian's message.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} spoke with Denalan at Rellian's request.",["sourceHash"]="be26997aea3f222f090efc424e6b6f72b539ea81c03750ed222683bf10a0eccb",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2499]={["aftermath"]="Denalan remembered Oakenscowl as a leader among timberlings before corruption overtook him. The great tumor still needed study to explain the disease afflicting the population.",["atomIDs"]={"2499:description:1-157","2499:description:162-298","2499:description:301-333","2499:description:338-418","2499:description:420-509","2499:objective:1-83"},["bridge"]="The inquiry had returned to Denalan and the shore of Lake Al'Ameth. He identified Oakenscowl's huge tumor as a source of spreading corruption and asked for its removal and recovery.",["bridgeFrom"]=2498,["bridgeReplacesSetup"]=true,["endingAtomIDs"]={"2499:completion:1-77","2499:completion:82-166","2499:completion:168-236","2499:completion:241-374","2499:completion:379-392"},["opening"]="Denalan identified Oakenscowl, a timberling in a cave on the lake's southern shore, as a spreading source of corruption. Even at a distance he could see an enormous tumor; he asked that it be removed.",["pending"]="{actor} meant to recover the Gargantuan Tumor from Oakenscowl.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered Oakenscowl's Gargantuan Tumor to Denalan.",["sourceHash"]="7e2b4bc0fb6b421f14c6ae8b2aa2084389f264af4323c28605863fb632888458",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2500]={["atomIDs"]={"2500:description:1-38","2500:description:41-145","2500:description:150-277","2500:description:280-398","2500:description:403-467","2500:description:472-489","2500:objective:1-93"},["opening"]="Ghak sought reagents to replenish his alchemical stocks in Thelsamar. His list led into the Badlands for buzzard gizzards, crag coyote fangs and rock elemental shards.",["pending"]="{actor} intended to obtain five gizzards, ten fangs and five elemental shards for Ghak.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the requested Badlands reagents to Ghak Healtouch.",["sourceHash"]="33a1b9d11cca6102ebb6bb4bdecf8657ce9da93add113694efb6ace44c3537c0",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2501]={["atomIDs"]={"2501:description:1-37","2501:description:40-174","2501:description:179-329","2501:description:332-391","2501:description:394-442","2501:description:447-484","2501:objective:1-85","2501:objective:88-156"},["opening"]="Ghak offered a recipe in exchange for a dangerous favor. Three attuned vessels could drain blood from the Badlands' scorched guardian dragons, but using them would provoke the creatures.",["pending"]="{actor} planned to fill the three Thaumaturgy Vessels and return them to Ghak.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the three filled Thaumaturgy Vessels to Ghak Healtouch.",["sourceHash"]="f7f7c8a28ad1e06de48d9b1ccf7e4698b411b5f741b0ad8a0fc88fc3e2dc9670",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2518]={["atomIDs"]={"2518:description:1-39","2518:description:41-143","2518:description:145-218","2518:description:223-270","2518:description:272-321","2518:description:326-370","2518:description:372-445","2518:description:447-502","2518:objective:1-114"},["opening"]="A'moora remembered Sathrah spinning silver dew with healing power for the temple. Madness now threatened both the spider and her descendants, and the priestess asked for the silvery spinnerets after her suffering ended.",["pending"]="{actor} meant to recover Lady Sathrah's Silvery Spinnerets for A'moora.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered Lady Sathrah's Silvery Spinnerets to Priestess A'moora.",["sourceClassMask"]="?",["sourceHash"]="e8e8b5db0d2d3fbcc9ca2009530fc488325d85ed6fcd2ca42c43a40f2d312ed0",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2519]={["atomIDs"]={"2519:description:1-59","2519:description:64-107","2519:description:112-177","2519:description:179-243","2519:objective:1-83"},["opening"]="Aquinne spoke of a once-great forest creature needing difficult help. A'moora at the Temple of the Moon could explain what the visitor was being asked to do.",["pending"]="{actor} intended to speak with Priestess A'moora.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} spoke with Priestess A'moora in the Temple of the Moon.",["sourceClassMask"]="?",["sourceHash"]="a83017d6df01a3dc9534ebbb502d513b7a91714dd1458ac6a4c8236e7e9fa3cd",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2520]={["aftermath"]="A'moora regarded the offering as a way for Sathrah's spirit to be renewed. Her prayer sought Elune's acceptance while acknowledging the loss of the creature.",["atomIDs"]={"2520:description:1-62","2520:description:64-157","2520:description:162-207","2520:description:209-251","2520:description:254-331","2520:description:336-378","2520:objective:1-129"},["bridge"]="Sathrah's spinnerets had reached A'moora. Their final destination was the temple fountain, where the priestess expected the waters to cleanse the corruption in an offering to Elune.",["bridgeFrom"]=2518,["bridgeReplacesSetup"]=true,["endingAtomIDs"]={"2520:completion:1-102","2520:completion:107-173"},["opening"]="A'moora directed Sathrah's spinnerets into the temple's central fountain. She believed the holy water would cleanse the corruption and complete the offering to Elune.",["pending"]="{actor} planned to place Sathrah's spinnerets at the fountain and return to A'moora.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the fountain offering and returned to Priestess A'moora.",["sourceClassMask"]="?",["sourceHash"]="fd36dc9c19e26c44aafd6bbc141b170e941afbcbcf5cd5fa3c5f55e2593d281a",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2521]={["aftermath"]="The rare find renewed Kum'isha's hope of opening a rift to the draenei homeland.",["atomIDs"]={"2521:description:1-87","2521:description:89-213","2521:description:218-308","2521:description:310-325","2521:description:327-506","2521:objective:1-151","2521:objective:156-226","2521:objective:228-302","2521:objective:307-383"},["endingAtomIDs"]={"2521:completion:1-22","2521:completion:24-34","2521:completion:36-51","2521:completion:53-58","2521:completion:63-125"},["opening"]="Kum'isha described flawless draenethyst spheres as a rarity that had consumed entire lifetimes of searching. He offered payment if one surfaced in the Blasted Lands.",["pending"]="{actor} meant to bring a flawless sphere to the collector.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered a flawless sphere to Kum'isha.",["sourceHash"]="4273987dc1112b498f586982b26e335a0ffad519db9919a7a337ce83dd8f78b5",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2522]={["atomIDs"]={"2522:description:1-107","2522:description:112-180","2522:description:182-265","2522:description:270-345","2522:objective:1-72"},["opening"]="The portal attempt had failed, but Kum'isha remained hopeful. Another flawless sphere would support a further attempt rather than guarantee its success.",["pending"]="{actor} intended to seek another sphere for Kum'isha.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} supplied the collector with another flawless sphere.",["sourceHash"]="8b416965f7275aa35ea352bce8460a6dbad180ab6ba42e7490f46aaf5e861146",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2581]={["aftermath"]="Drazial reported that the supplied components yielded only one tablet, requiring new materials for any further preparation.",["atomIDs"]={"2581:description:1-143","2581:description:145-223","2581:description:228-303","2581:description:305-471","2581:objective:1-99"},["endingAtomIDs"]={"2581:completion:1-20","2581:completion:22-103","2581:completion:108-214","2581:completion:216-281"},["opening"]="Drazial claimed to have witnessed extraordinary force in snickerfang jaws. An assay combining jowls, boar lungs and a scorpok pincer would investigate it.",["pending"]="{actor} planned to gather the first strength-assay materials.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the jowls, lungs and pincer to Drazial.",["sourceHash"]="959b5bfbef420256dceb97df97de9a855b9199a1b58144f2363672273c2819ea",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2582]={["aftermath"]="Drazial advised sparing use and offered another preparation once the current one was finished.",["atomIDs"]={"2582:description:1-21","2582:description:23-113","2582:description:115-257","2582:description:262-297","2582:description:299-394","2582:objective:1-99"},["endingAtomIDs"]={"2582:completion:1-13","2582:completion:15-41","2582:completion:43-141"},["opening"]="Drazial warned that the strength preparation might endanger spirit and intellect over time. Making another dose required the same three animal materials.",["pending"]="{actor} meant to gather components for another strength assay.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the requested components to Drazial.",["sourceHash"]="e75c43234e2b642adc3a15d8a37eff47d057f829f7253485ba1a07de57f86ff7",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2583]={["atomIDs"]={"2583:description:1-89","2583:description:94-270","2583:description:275-314","2583:description:316-467","2583:description:469-502","2583:objective:1-97"},["opening"]="Drazial considered the local boars unusually resistant to harm. Lungs, pincers and a basilisk brain were to supply a new assay, with its bearer proposed as the first test subject.",["pending"]="{actor} intended to gather the vitality experiment's materials.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} brought the lungs, pincers and brain to Drazial.",["sourceHash"]="131546d52d1c5f22e18af4c937955c6e2f2e5cef4c09ea3fcc352372f0c36888",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2584]={["aftermath"]="Drazial warned that the latest formula would displace earlier enchantments, making their effects mutually exclusive.",["atomIDs"]={"2584:description:1-116","2584:description:118-161","2584:description:163-261","2584:description:276-445","2584:objective:1-97"},["endingAtomIDs"]={"2584:completion:1-71","2584:completion:73-235"},["opening"]="Drazial described addictive properties in his boar-derived mixture. He offered to make more if another set of lungs, pincers and a brain were obtained.",["pending"]="{actor} planned to gather another set for the boar assay.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} supplied Drazial's further boar experiment.",["sourceHash"]="e583e7d9ef611bdcda67d14b307805e37ba84b265b1720b8c2b5952487775ac1",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2585]={["aftermath"]="Drazial offered a pinch of residual salt, describing euphoria followed by exceptional agility as its expected effects.",["atomIDs"]={"2585:description:1-41","2585:description:43-63","2585:description:65-126","2585:description:128-161","2585:description:166-264","2585:description:266-274","2585:description:276-323","2585:description:328-388","2585:description:393-511","2585:objective:1-98"},["endingAtomIDs"]={"2585:completion:1-12","2585:completion:14-71","2585:completion:76-141","2585:completion:143-252"},["opening"]="The scorpoks' precise movement suggested an agility assay to Drazial. Pincers, gizzards and one lung were needed to make its stable sample.",["pending"]="{actor} meant to collect the agility assay's materials.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the pincers, gizzards and lung.",["sourceHash"]="dc1fd3b3a2f2352e29ff184bf0cc75c8d23acab2821e5545ec14dfb0201bdbf4",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2586]={["aftermath"]="Drazial divided the preparation between one offered sample and nine retained for research.",["atomIDs"]={"2586:description:1-9","2586:description:11-36","2586:description:38-89","2586:description:94-253","2586:objective:1-98"},["endingAtomIDs"]={"2586:completion:1-14","2586:completion:16-106","2586:completion:111-206"},["opening"]="Drazial offered another scorpok preparation on the same terms. Its renewal depended on three pincers, two gizzards and a boar lung.",["pending"]="{actor} intended to gather another scorpok assay's components.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} brought the requested components to Drazial.",["sourceHash"]="8a18d8b94ae64d879c2ebacaed98fc523bd73517b502d6b8ddb5c6171bdcc5fd",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2601]={["atomIDs"]={"2601:description:1-56","2601:description:58-158","2601:description:163-313","2601:description:318-343","2601:description:348-387","2601:description:389-492","2601:objective:1-72"},["opening"]="Lynnore had watched redstone basilisks display unexpectedly complex behavior. Their brains, with gizzards as a base, would support her study of that adaptation.",["pending"]="{actor} planned to gather ten brains and two gizzards.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} supplied Lynnore with the assay materials.",["sourceHash"]="4f8c0b19f501f3ec74c923cd09f9a9332d8cd083193c006d647b5e653e8683c1",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2602]={["aftermath"]="Lynnore cautioned against consuming the experimental mixtures in rapid succession.",["atomIDs"]={"2602:description:1-48","2602:description:50-76","2602:description:81-119","2602:description:121-233","2602:objective:1-72"},["endingAtomIDs"]={"2602:completion:1-91","2602:completion:96-105","2602:completion:107-191","2602:completion:193-224"},["opening"]="Lynnore offered more of the concentration compound for another collection. Its cost remained ten basilisk brains and two vulture gizzards.",["pending"]="{actor} meant to collect the next concentration assay's materials.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the brains and gizzards to Lynnore.",["sourceHash"]="8bbda6ab808d2a4d112cdb2793c903cfeabde3c08dba9832442f511cf6a9845d",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2603]={["aftermath"]="Lynnore hoped the study might uncover remedies, leaving any cure a future possibility.",["atomIDs"]={"2603:description:1-56","2603:description:58-230","2603:description:232-328","2603:description:333-360","2603:description:362-377","2603:description:379-453","2603:description:458-505","2603:objective:1-74"},["endingAtomIDs"]={"2603:completion:1-15","2603:completion:17-48","2603:completion:50-117","2603:completion:122-239"},["opening"]="Vultures fed on diseased carcasses yet survived the wasteland. Lynnore wanted to study that resilience through gizzards, using jowls as the mixture's base.",["pending"]="{actor} intended to gather ten gizzards and two jowls.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} brought Lynnore the requested specimens.",["sourceHash"]="b5b062033db79b76e38075744fda88277566da92bf165f5335649487e815947b",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2604]={["aftermath"]="Lynnore hoped eventually to isolate the active enzymes and produce a more efficient result.",["atomIDs"]={"2604:description:1-39","2604:description:41-92","2604:description:97-176","2604:description:178-204","2604:description:206-271","2604:objective:1-74"},["endingAtomIDs"]={"2604:completion:1-120","2604:completion:122-200","2604:completion:202-250"},["opening"]="Lynnore's further preparation called for more of the same two components. Her interest in its effects did not alter the requirements of the assay.",["pending"]="{actor} planned to renew the supply of gizzards and jowls.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered another set of components.",["sourceHash"]="5902ffa218fca1e07d384e959704ef27668053081fbbd7de003cae8bd9d214b2",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2605]={["atomIDs"]={"2605:description:1-22","2605:description:24-111","2605:description:113-168","2605:description:173-281","2605:description:283-317","2605:description:322-397","2605:objective:1-74"},["opening"]="Marin's thirst had suggested an experiment with dew collectors. He believed their water-filled glands could yield a satisfying drink and pointed toward the southwestern cactus garden for one.",["pending"]="{actor} meant to recover a Laden Dew Gland for Marin.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered a Laden Dew Gland to Marin Noggenfogger.",["sourceClassMask"]="?",["sourceHash"]="beb740f8a5260719024ac19d74146db809ab39b3d978b016ad0c2a6866ebf976",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2606]={["atomIDs"]={"2606:description:1-6","2606:description:8-34","2606:description:36-59","2606:description:64-81","2606:description:83-146","2606:description:148-163","2606:description:168-189","2606:description:191-200","2606:description:202-264","2606:description:266-348","2606:description:353-435","2606:description:437-466","2606:objective:1-65"},["bridge"]="The dew gland had reached Marin, but its taste ruined his first idea for a drink. Sprinkle's cooking skill offered another way to make the experiment tolerable.",["bridgeFrom"]=2605,["bridgeReplacesSetup"]=true,["opening"]="The dew tasted terrible, but Marin was not quite ready to abandon it. Sprinkle's skill as a chef might make the proposed drink tolerable, so the experiment moved into her hands.",["pending"]="{actor} intended to speak with Sprinkle about Marin's dew.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} spoke with Sprinkle in Gadgetzan.",["sourceClassMask"]="?",["sourceHash"]="5c3785f318e4a85f3cf13df96a88208b707ae997e05c4d9fbcfb235a57499f94",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2607]={["atomIDs"]={"2607:description:1-75","2607:description:77-123","2607:description:128-134","2607:description:136-141","2607:description:143-219","2607:objective:1-56"},["opening"]="Shaw found the returned information accompanied by a strange need for treatment. The doctor in the Barracks cellar was the person he suggested for a cure.",["pending"]="{actor} intended to consult Doc Mixilpixil.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} spoke with Doc Mixilpixil in the cellar.",["sourceClassMask"]="8",["sourceHash"]="4af9aa52094a60a559523f025232015b17a221c280eaf1871774d645603caece",["sourceMapID"]="?",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2608]={["atomIDs"]={"2608:description:1-27","2608:description:29-84","2608:description:86-156","2608:description:161-164","2608:description:166-185","2608:description:187-206","2608:description:211-285","2608:description:287-329","2608:description:331-350","2608:description:352-401","2608:objective:1-43","2608:objective:45-96"},["opening"]="The doctor's insults preceded a blood test. Lying down for examination was his requested first step toward finding the cause and a possible cure.",["pending"]="{actor} meant to lie down for Doc Mixilpixil's examination.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the prescribed examination by Doc Mixilpixil.",["sourceClassMask"]="8",["sourceHash"]="c1d00b7054e61af6ffdbdf17bffa6e05ebec7ac46faff32acddd18d27b54e5e4",["sourceMapID"]="?",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2609]={["atomIDs"]={"2609:description:1-19","2609:description:21-42","2609:description:47-84","2609:description:89-252","2609:description:254-351","2609:description:356-423","2609:description:425-435","2609:description:437-493","2609:objective:1-135","2609:objective:137-189"},["opening"]="Mixilpixil called the condition the itis and prescribed an odd supply list. Thread left by Emma at the canal shop joined flowers, a vial and a bronze tube as the claimed cure's requirements.",["pending"]="{actor} planned to obtain the four items requested by Mixilpixil.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered Simple Wildflowers, a Leaded Vial, a Bronze Tube and Light Chartreuse Silk Thread to Doc Mixilpixil.",["sourceClassMask"]="8",["sourceHash"]="9f7743d01935aca239d1fc556bed210123b4c82c0f74539c716677976270710c",["sourceMapID"]="?",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2621]={["aftermath"]="Ruag remembered the destruction of the regiment and the soldiers lost with it.",["atomIDs"]={"2621:description:1-7","2621:description:9-29","2621:description:31-86","2621:description:88-125","2621:description:127-207","2621:description:209-257","2621:description:259-286","2621:description:288-310","2621:description:315-347","2621:description:349-360","2621:description:362-386","2621:description:391-433","2621:description:435-482","2621:objective:1-44"},["endingAtomIDs"]={"2621:completion:1-17","2621:completion:19-54","2621:completion:59-90","2621:completion:95-140","2621:completion:142-216"},["opening"]="The fallen commander blamed a decision made before orders arrived. He needed to know what those missing instructions would have said.",["pending"]="{actor} meant to ask Ruag about the lost dispatch.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} reached Ruag in Stonard.",["sourceHash"]="a3436e9c2057934b6497883d71f3c1c22867f188d95c0a06b3f7da6d59ef4e5c",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2622]={["atomIDs"]={"2622:description:1-11","2622:description:13-57","2622:description:62-87","2622:description:89-121","2622:description:123-203","2622:description:205-254","2622:description:256-320","2622:description:322-390","2622:description:392-430","2622:description:432-508","2622:objective:1-16"},["opening"]="Ruag insisted he had dispatched the orders. He said murlocs ambushed the couriers and directed the inquiry toward their gravely injured sole survivor.",["pending"]="{actor} intended to seek Bengor's account.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} spoke with Bengor about the missing orders.",["sourceHash"]="ab8918bafc3f915432e5291f946820f7c3481e970d89b6fd3ebb7160b435b770",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2623]={["aftermath"]="The commander concluded that nineteen soldiers might have been spared and asked for help for those still trapped.",["atomIDs"]={"2623:description:1-44","2623:description:46-55","2623:description:57-68","2623:description:70-103","2623:description:108-117","2623:description:119-133","2623:description:135-157","2623:description:159-214","2623:description:216-222","2623:description:224-231","2623:description:236-255","2623:objective:1-79"},["endingAtomIDs"]={"2623:completion:1-28","2623:completion:30-103","2623:completion:105-144","2623:completion:149-171","2623:completion:173-194"},["opening"]="Bengor recalled the eastern cave and the named murloc who seized the orders during the ambush. The dispatch could still answer the fallen commander's question.",["pending"]="{actor} planned to recover the Warchief's orders.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} returned the recovered dispatch to the fallen hero.",["sourceHash"]="46e1568bbc6f10c45474fff23d45aec579d9a974c3054bc4f6021a2d109ce2dd",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2641]={["atomIDs"]={"2641:description:1-55","2641:description:57-72","2641:description:74-180","2641:description:182-207","2641:description:209-212","2641:description:214-229","2641:description:234-253","2641:description:255-295","2641:description:297-433","2641:description:438-502","2641:objective:1-80"},["bridge"]="The dew problem had reached Sprinkle. Her answer was Violet Tragan, an underwater mushroom in a Hinterlands lake that she trusted to improve almost any dish.",["bridgeFrom"]=2606,["bridgeReplacesSetup"]=true,["opening"]="Sprinkle remembered a mushroom that had rescued even her sister's worst cooking. A Violet Tragan growing underwater in a Hinterlands lake was her proposed answer to Marin's bitter brew.",["pending"]="{actor} planned to obtain a Violet Tragan for Sprinkle.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered a Violet Tragan to Sprinkle.",["sourceClassMask"]="?",["sourceHash"]="45144a80f90029fb2590096a0b095fe15ca43875ba6ffd01bcfc94c7580a4e06",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2661]={["atomIDs"]={"2661:description:1-29","2661:description:31-79","2661:objective:1-80"},["bridge"]="The mushroom had reached Sprinkle and become Violet Powder. The prepared ingredient was ready to return to Marin with a reminder that he owed her a favor.",["bridgeFrom"]=2641,["bridgeReplacesSetup"]=true,["opening"]="Sprinkle had prepared the Violet Powder. It needed to return to Marin, along with her reminder that the assistance left him owing a favor.",["pending"]="{actor} meant to take the Violet Powder to Marin.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the Violet Powder to Marin Noggenfogger.",["sourceClassMask"]="?",["sourceHash"]="f7c126f834af8f7bc3d4ce8e87f07632cc45c5546bb30d4c90c25c01ccc2bf4f",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2662]={["aftermath"]="Marin proclaimed the elixir a commercial triumph and dismissed Sprinkle's reminder of a favor. The response recorded his enthusiasm, not an observed effect from anyone drinking it.",["atomIDs"]={"2662:description:1-40","2662:description:45-83","2662:description:85-140","2662:objective:1-79"},["bridge"]="The powder had reached Marin. Mixing it with the dew was now the last preparation before another conversation could reveal what his elixir had become.",["bridgeFrom"]=2661,["bridgeReplacesSetup"]=true,["endingAtomIDs"]={"2662:completion:1-11","2662:completion:13-40","2662:completion:45-68","2662:completion:70-153","2662:completion:155-182","2662:completion:184-256","2662:completion:261-272","2662:completion:274-305","2662:completion:307-339"},["opening"]="Marin was ready to mix Sprinkle's powder with the dew. The new elixir still required a short wait before he could pronounce the experiment finished.",["pending"]="{actor} intended to return after Marin prepared his elixir.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} spoke with Marin again after the elixir preparation.",["sourceClassMask"]="?",["sourceHash"]="810dc9ebc8928e2349ae8ef566492b651b561f3d164a619983fa759d9badfc83",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2681]={["aftermath"]="The commander confirmed that the tortured souls could rest, while further work remained.",["atomIDs"]={"2681:description:1-89","2681:description:94-173","2681:description:175-207","2681:description:212-245","2681:objective:1-114","2681:objective:116-168","2681:objective:170-247"},["endingAtomIDs"]={"2681:completion:1-21","2681:completion:23-64","2681:completion:69-97","2681:completion:99-150"},["opening"]="The commander's men remained bound to eighteen stones under demonic control. Shattering them near the servants was the means offered to end their torture.",["pending"]="{actor} meant to break the bindings on eighteen servants.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the freeing of the bound servants.",["sourceHash"]="7f53a8d18e8767fe5195525ca15e051436006620db6d466923556a4b4fe260b5",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2701]={["atomIDs"]={"2701:description:1-38","2701:description:40-76","2701:description:81-135","2701:objective:1-37"},["opening"]="Thund offered an old relic his companions no longer needed. A chest held the gift intended for continued opposition to the Legion.",["pending"]="{actor} intended to open the offered chest.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} opened Thund's chest.",["sourceHash"]="e48a5bf716ec9267387ff51c913d1bb064a08c4d40093390d277ba76f264a747",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2702]={["aftermath"]="Thund said thanks alone would not suffice for the service done.",["atomIDs"]={"2702:description:1-55","2702:description:60-88","2702:objective:1-34"},["endingAtomIDs"]={"2702:completion:1-32","2702:completion:34-69"},["opening"]="The fallen commander directed acknowledgment beyond himself toward the soldiers. Thund was to receive the next visit after their release.",["pending"]="{actor} planned to speak with Corporal Thund.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} met the corporal.",["sourceHash"]="050f0c8fa814eb32438b8ec08ac5e6aa99cfcaff7e651be7b87b281e665d393d",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2721]={["atomIDs"]={"2721:description:1-64","2721:description:69-144","2721:description:146-193","2721:description:198-323","2721:description:325-423","2721:description:425-467","2721:objective:1-42"},["opening"]="One lieutenant remained unaccounted for. The commander last heard Kirith suffering under Allistarj's experiments and knew neither his later fate nor his location.",["pending"]="{actor} meant to discover what became of Kirith.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} reached Kirith's spirit.",["sourceHash"]="224e8b00c2b12de6c596be1ebe8608c71524499b3edf5a7bc39e84e45bab8ed6",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2742]={["aftermath"]="The markings could not yet be deciphered, leaving Oran as a possible interpreter.",["atomIDs"]={"2742:description:1-7","2742:description:12-44","2742:description:46-72","2742:description:74-140","2742:description:142-162","2742:description:167-257","2742:description:262-318","2742:objective:1-106"},["endingAtomIDs"]={"2742:completion:1-69","2742:completion:74-146","2742:completion:151-210","2742:completion:212-262"},["opening"]="Rin'ji had lost his axe and been captured at the lodge. He begged for an escape despite expecting hostility toward his kind, offering a hidden object at the cliffs in return.",["pending"]="{actor} intended to escort Rin'ji and seek his secret.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the escape and found the hidden tablet.",["sourceHash"]="3146a33aaddf7abdfb1033c85cc71568b3d6dea55c2612714356da12047a6594",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2743]={["atomIDs"]={"2743:description:1-52","2743:description:57-132","2743:description:134-196","2743:description:201-215","2743:description:220-326","2743:description:328-396","2743:description:401-466","2743:description:468-507","2743:objective:1-58"},["opening"]="Kirith described an amulet divided among three demon servants. Its pieces were both their source of protection and the key needed to summon their lord.",["pending"]="{actor} intended to carry Kirith's explanation back.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} reported the findings to the fallen commander.",["sourceHash"]="d1fa4075cc5575b6a0c865519f8a966c86f3d32cb3c668bff81480e5ffb79abc",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2744]={["aftermath"]="Loramus agreed to help while warning that the full danger was not yet understood.",["atomIDs"]={"2744:description:1-35","2744:description:40-150","2744:description:152-245","2744:description:247-365","2744:description:370-424","2744:description:426-489","2744:description:491-509","2744:objective:1-41"},["endingAtomIDs"]={"2744:completion:1-16","2744:completion:18-87"},["opening"]="The commander explained that the amulet bound each servant's life to its piece. Loramus might know how to overcome that protection within the Blasted Lands.",["pending"]="{actor} planned to seek Loramus among Azshara's islands.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} reached Loramus.",["sourceHash"]="40667780bdaf53deccb2c4c67b16be80738b9aeef8a8808f0f19beffa9c992e0",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2745]={["atomIDs"]={"2745:description:1-58","2745:description:60-149","2745:description:151-198","2745:description:203-257","2745:description:259-302","2745:description:307-317","2745:description:319-408","2745:description:410-460","2745:description:462-500","2745:objective:1-36"},["bridge"]="Trias proposed an approach outside ordinary law. Tyrion had watched Lescovar for weeks and could prepare the next move inside the castle.",["bridgeFrom"]=350,["bridgeReplacesSetup"]=true,["opening"]="Trias warned that confronting Lescovar and Marzon would require justice outside the law. Tyrion had watched the noble for weeks and could prepare the next step inside the castle.",["pending"]="{actor} meant to find Tyrion at Stormwind Castle.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} spoke with Tyrion in Stormwind Castle.",["sourceClassMask"]="?",["sourceHash"]="1e597bf876edd1ac98bc475d52db65c3ceafb2973ed7a3ad8a0a4f8eef4da5ba",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2746]={["atomIDs"]={"2746:description:1-46","2746:description:48-87","2746:description:89-203","2746:description:205-209","2746:description:214-293","2746:description:295-358","2746:description:363-401","2746:description:403-500","2746:objective:1-72"},["bridge"]="The castle inquiry had reached Tyrion, who was willing to advance his plan. Three pieces of silk and two apples were still needed for Spybot's disguise.",["bridgeFrom"]=2745,["bridgeReplacesSetup"]=true,["opening"]="Tyrion could advance the timetable but lacked materials for Spybot's disguise. Silk and apples from Clara's nearby farm were needed before the deception could pass the guards.",["pending"]="{actor} intended to bring three Silk Cloth and two Clara's Fresh Apples to Tyrion.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered three Silk Cloth and two Clara's Fresh Apples to Tyrion.",["sourceClassMask"]="?",["sourceHash"]="058894b1737fe8ca29cea8b92119f34183932b6e325989ec00f5bbbd561abfa4",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2751]={["atomIDs"]={"2751:description:1-54","2751:description:56-103","2751:description:105-209","2751:description:214-266","2751:description:268-314","2751:description:319-353","2751:description:355-459","2751:description:461-503","2751:objective:1-108"},["opening"]="Orokk feared the Omosh smithing legacy would end without kin to inherit it. He chose skill over ancestry, demanding bronze work and claws as the first proof of a successor's capability.",["pending"]="{actor} intended to bring two Patterned Bronze Bracers, two Bronze Greatswords and two Sharp Claws.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the three requested pairs to Orokk Omosh.",["sourceClassMask"]="?",["sourceHash"]="1199014f20567b1e87855ef5939f03acc74682b79c0112afe439f68bacd5e2f8",["sourceMapID"]="?",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2752]={["atomIDs"]={"2752:description:1-42","2752:description:44-93","2752:description:98-125","2752:description:130-248","2752:description:250-295","2752:objective:1-84"},["opening"]="The next Omosh lesson returned to the anvil. Four battleaxes and four warhammers in bronze were the work required before Orokk would teach the iron pauldron.",["pending"]="{actor} meant to make four Bronze Battleaxes and four Bronze Warhammers for Orokk.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered four Bronze Battleaxes and four Bronze Warhammers to Orokk Omosh.",["sourceClassMask"]="?",["sourceHash"]="f5beece6f88b5a0954628672085476f8e96f3458cc306a80146d0a36923e7c29",["sourceMapID"]="?",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2753]={["atomIDs"]={"2753:description:1-43","2753:description:45-101","2753:description:106-241","2753:objective:1-110"},["opening"]="Orokk Omosh pressed onward despite the strain of the forge. Only two lessons remained, and green iron armor would demonstrate the persistence he expected from a pupil.",["pending"]="{actor} planned to bring four Green Iron Helms, four Green Iron Bracers, and two Green Iron Leggings to Orokk.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered four Green Iron Helms, four Green Iron Bracers, and two Green Iron Leggings to Orokk Omosh.",["sourceClassMask"]="?",["sourceHash"]="dca888fb67e8e5da7434968a1cd78d4e6cb7165b1c54737fa9571bb5dd420c62",["sourceMapID"]="?",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2754]={["atomIDs"]={"2754:description:1-39","2754:description:41-81","2754:description:83-181","2754:description:186-228","2754:objective:1-117"},["opening"]="Orokk's final forging lesson required weapons alongside bronze armor. His teaching had reached the point where two solid mauls and matched pieces of silvered bronze would complete the practical work.",["pending"]="{actor} intended to supply two Solid Iron Mauls, two Silvered Bronze Boots, and two Silvered Bronze Gauntlets.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} brought two Solid Iron Mauls, two Silvered Bronze Boots, and two Silvered Bronze Gauntlets to Orokk Omosh.",["sourceClassMask"]="?",["sourceHash"]="89a03755b58bdb190a950bd82841af617b3849b40f56e16784bc2d6313fe426c",["sourceMapID"]="?",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2755]={["atomIDs"]={"2755:description:1-24","2755:description:26-40","2755:description:45-70","2755:description:75-133","2755:description:135-169","2755:description:174-230","2755:objective:1-39"},["opening"]="Orokk brushed at a tear and blamed the soot. One family secret remained after the forge work: the Omosh Dance of Joy, which he offered as a lesson in making fists as hard as iron.",["pending"]="{actor} meant to watch Orokk and learn the Omosh Dance of Joy.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed Orokk Omosh's lesson in the Dance of Joy.",["sourceClassMask"]="?",["sourceHash"]="1b8efa9cd7ad803ad20a1fd89856220aa457581bc82388329cb5018486747267",["sourceMapID"]="?",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2756]={["atomIDs"]={"2756:description:1-126","2756:description:128-156","2756:description:158-202","2756:description:204-252","2756:description:257-309","2756:description:314-330","2756:description:332-373","2756:description:375-461","2756:objective:1-89"},["opening"]="Aturk remembered smithing before peace had changed the clans' needs. Bone powder had once bound his steel, and he wanted a pupil to learn the old methods through breastplates and helms.",["pending"]="{actor} planned to bring four Steel Breastplates and four Steel Plate Helms to Aturk.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered four Steel Breastplates and four Steel Plate Helms to Aturk the Anvil.",["sourceClassMask"]="?",["sourceHash"]="2ae5c816841492e34071b3317b49373e356a0c148811813793b3b285f506dcaf",["sourceMapID"]="?",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2757]={["atomIDs"]={"2757:description:1-65","2757:description:70-98","2757:description:100-139","2757:description:141-204","2757:description:209-224","2757:description:226-299","2757:description:304-344","2757:description:346-403","2757:objective:1-32"},["opening"]="Ox offered an insignia as proof of commitment to further smithing. The next contact was McGavan by the Booty Bay smithy, where the search for instruction in mithril could begin.",["pending"]="{actor} intended to carry the Mithril Insignia to McGavan in Booty Bay.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the Mithril Insignia to McGavan.",["sourceClassMask"]="?",["sourceHash"]="83291e18173615fafac374d99725517a4c2a8acc027c86573f25556d89ead8e4",["sourceMapID"]="?",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2758]={["atomIDs"]={"2758:description:1-125","2758:description:127-310","2758:description:315-368","2758:description:370-451","2758:objective:1-63"},["opening"]="Hank the Hammer owed his armorsmithing knowledge to Galvan. Before his teacher left Booty Bay, Hank had promised to pass those skills on; golden scale bracers were the work he set for a new pupil.",["pending"]="{actor} planned to bring six Golden Scale Bracers to Hank the Hammer.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered six Golden Scale Bracers to Hank the Hammer.",["sourceClassMask"]="?",["sourceHash"]="4d34830cd1977b7d07172eca891f2d25bb3bbe2666a11047d6f8189c1022ebaa",["sourceMapID"]="?",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2759]={["atomIDs"]={"2759:description:1-149","2759:description:154-211","2759:description:216-280","2759:description:282-298","2759:objective:1-32"},["opening"]="Years had passed since Galvan left Booty Bay, but his order still sought promising smiths. Hank gave an insignia to a prospective pupil and directed the search toward McGavan.",["pending"]="{actor} meant to take the Mithril Insignia to McGavan in Booty Bay.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the Mithril Insignia to McGavan.",["sourceClassMask"]="?",["sourceHash"]="31e24ce1ea4e43ca4f714b8d89b5d8ad1099dded6b6c7ca4575358a8e4e625cd",["sourceMapID"]="?",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2760]={["atomIDs"]={"2760:description:1-52","2760:description:54-152","2760:description:154-251","2760:description:256-301","2760:description:303-383","2760:objective:1-52"},["opening"]="McGavan knew that a recruit could sell the insignia for quick coin. Keeping it for the order's lessons offered a different prospect, beginning with Galvan far north between Zul'Gurub and the Mosh'Ogg mound.",["pending"]="{actor} planned to seek Galvan the Ancient in northern Stranglethorn.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} reached Galvan the Ancient for the Mithril Order's instruction.",["sourceClassMask"]="?",["sourceHash"]="ab2ffd528d1e668c7c9c151720190e4eebffc4aca03a028d1eef4e9e78b3f718",["sourceMapID"]="?",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2761]={["atomIDs"]={"2761:description:1-128","2761:description:130-161","2761:description:163-225","2761:description:230-266","2761:description:268-321","2761:description:323-391","2761:objective:1-84"},["opening"]="Galvan treated mining and smithing as inseparable disciplines. A supply of iron and mithril would support his first lesson in shaping the order's ornate armor.",["pending"]="{actor} intended to bring forty Mithril Bars and forty Iron Bars to Galvan.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered forty Mithril Bars and forty Iron Bars to Galvan the Ancient.",["sourceClassMask"]="?",["sourceHash"]="c2f7b8c9737dc5077fddf08e8f7b023d83adb5b7ec3099c99ff9831d2f489b5f",["sourceMapID"]="?",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2762]={["atomIDs"]={"2762:description:1-69","2762:description:71-182","2762:description:184-215","2762:description:217-220","2762:description:222-301","2762:description:306-364","2762:description:366-487","2762:objective:1-89"},["opening"]="Galvan admitted truesilver's strength but held mithril above it in a smith's calling. His next lesson required both metals, with the smaller truesilver portion serving work devoted chiefly to mithril.",["pending"]="{actor} planned to supply forty Mithril Bars and five Truesilver Bars.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} brought forty Mithril Bars and five Truesilver Bars to Galvan the Ancient.",["sourceClassMask"]="?",["sourceHash"]="5ab707c4ab743858fe5e2ef8edb94670990d9b35521c74b60fb7cc8b6f2243d1",["sourceMapID"]="?",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2763]={["atomIDs"]={"2763:description:1-73","2763:description:75-118","2763:description:120-215","2763:description:220-293","2763:description:295-409","2763:objective:1-82"},["opening"]="Galvan's work depended on more than shaped metal. Citrine could amplify the magic within a piece, and he set aside an ornate shoulder design for a pupil who supplied gems and mithril.",["pending"]="{actor} meant to bring forty Mithril Bars and four Citrines to Galvan.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered forty Mithril Bars and four Citrines to Galvan the Ancient.",["sourceClassMask"]="?",["sourceHash"]="dabb49db143ce5694e855e08349d97cee150a75db3e97acb15cb3a57b2d74af4",["sourceMapID"]="?",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2764]={["atomIDs"]={"2764:description:1-88","2764:description:93-150","2764:description:152-206","2764:description:208-240","2764:description:245-283","2764:objective:1-44"},["opening"]="Galvan directed a trained pupil toward Trenton Lighthammer, whom he regarded as his finest student. The next exchange of knowledge lay in Gadgetzan, though Galvan's own lessons remained available.",["pending"]="{actor} intended to speak with Trenton Lighthammer in Gadgetzan.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} met Trenton Lighthammer to continue the smithing instruction.",["sourceClassMask"]="?",["sourceHash"]="a772462fc974f9a9e076a8ba8e33341651998f2cbe7480e59668def0afb384ce",["sourceMapID"]="?",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
