[2767]={["aftermath"]="Oglethorpe counted the recovery as a saving of rebuilding time and manufacturing expense. He still regarded the homing-robot series as unfinished development.",["atomIDs"]={"2767:description:1-53","2767:description:58-151","2767:description:154-234","2767:description:237-329","2767:description:332-402","2767:description:407-475","2767:description:478-505","2767:objective:1-105"},["bridge"]="The beacon had reached OOX-22/FE, but the robot still needed open ground for takeoff. Oglethorpe directed an escort to the Forgotten Coast dock while he restored the cloaking systems from his end.",["bridgeFrom"]=2766,["bridgeReplacesSetup"]=true,["endingAtomIDs"]={"2767:completion:1-41","2767:completion:43-103","2767:completion:105-273","2767:completion:278-331","2767:completion:333-414"},["opening"]="Oglethorpe needed the robot moved into the open while he restored its cloaking systems. The Forgotten Coast dock offered a place for the lengthy takeoff procedure, with a report afterward due in Booty Bay.",["pending"]="{actor} would escort OOX-22/FE to the coastal dock and report to Oglethorpe.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed OOX-22/FE's escort to the dock and reported to Oglethorpe Obnoticus.",["sourceClassMask"]="?",["sourceHash"]="85a8971787bcc0991a8928cf7dcbfa26d2ca6399c04cb7a5f691c27d6e00160d",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
