[2801]={["atomIDs"]={"2801:description:1-47","2801:objective:1-54"},["opening"]="The fallen commander required his account to be heard before the work could continue. Listening was the task that preceded any next action.",["pending"]="{actor} intended to hear the commander's story.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} listened to the fallen hero's account.",["sourceHash"]="b6f4aa51c2ec54eda820434a07b527349683a65a18fcd7893d4705f816891a27",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
