[2841]={["atomIDs"]={"2841:description:1-73","2841:description:75-103","2841:description:105-188","2841:description:190-215","2841:description:220-297","2841:description:299-388","2841:description:393-447","2841:description:449-506","2841:objective:1-115"},["opening"]="Nogg wanted the plans for a new gnomish rig that surpassed the shredder models he knew. The blueprints lay in a Gnomeregan safe, and Thermaplugg alone knew its combination.",["pending"]="{actor} meant to recover the Rig Blueprints and Thermaplugg's Safe Combination for Nogg.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the Rig Blueprints and Thermaplugg's Safe Combination to Nogg.",["sourceHash"]="1778273e2204934290a8300f90ace0293bed78fbfe6f8a7a4f2363d33467be67",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[2842]={["atomIDs"]={"2842:description:1-165","2842:description:170-216","2842:description:218-308","2842:description:310-357","2842:description:362-475","2842:objective:1-31"},["opening"]="Word of the gnomish rig had set Sovik and Scooty to work on a route into Gnomeregan. Their Transpolyporter was ready, and Scooty awaited passengers at Booty Bay's wind-rider roost.",["pending"]="{actor} intended to meet Scooty in Booty Bay.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} spoke with Scooty in Booty Bay.",["sourceHash"]="8a6ea55338a8350f710cb300e984b893920c2d47435ac0b33fbeddb31905ab05",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
