[2845]={["aftermath"]="Rockbiter learned that the bell could call Shay back when she wandered. Her return gave him a means to manage the problem that had first separated them.",["atomIDs"]={"2845:description:1-72","2845:description:74-109","2845:description:111-162","2845:description:164-225","2845:description:230-298","2845:description:303-368","2845:description:370-397","2845:description:399-490","2845:objective:1-35","2845:objective:40-82"},["bridge"]="The search had reached Shay, who acknowledged her habit of wandering. Her treasured bell could call her back during the escort to Rockbiter's camp.",["bridgeFrom"]=2844,["bridgeReplacesSetup"]=true,["endingAtomIDs"]={"2845:completion:1-5","2845:completion:7-52","2845:completion:54-74","2845:completion:79-123"},["opening"]="Shay admitted that the many things around her made her wander. A beloved bell in the nearby chest could call her back during the journey to Rockbiter's camp.",["pending"]="{actor} would retrieve Shay's Bell and escort her to Rockbiter.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed Shay Leafrunner's escort to Rockbiter's camp.",["sourceClassMask"]="?",["sourceHash"]="f8cffa09a27bccc125d26b297d4802a62c5a33cdd0ee8aeb7e93e2f7bd34ceb4",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
